const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {screen:'landing', user:null, authType:'user', authMode:'login', nextScreen:null, map:'Land Use Map', analysis:'Select Area', activeIntervention:null, uploadForIntervention:null, uploadStage:'Observation', photos:[], uploaded:[], interventions:[], geo:null, geoError:'', geoRequest:0, mapInstance:null, geoLayer:null, areaLayer:null, selectedArea:null, selectedPoint:null, locationLabel:'India · search to select an area', selectedCoords:null};
const mapOptions = ['Land Use Map','Drainage Map','Vegetation Map','Watershed Intervention'];
const analysisItems = ['Select Area','Land Use','Drainage','Vegetation','Soil Moisture','Water Bodies','Land Degradation','Interventions','Reports'];
const icon = {'Land Use Map':'▤','Drainage Map':'≋','Vegetation Map':'❧','Watershed Intervention':'♧','Land Use':'▤','Drainage':'≋','Vegetation':'❧','Soil Moisture':'◉','Water Bodies':'◌','Land Degradation':'△','Interventions':'♧','Upload Geotag Photos':'▧','Analytics':'▥','Reports':'▤'};

async function api(url, options={}) {
  const response = await fetch(url, { credentials:'same-origin', ...options, headers: {'Content-Type':'application/json', ...(options.headers||{})} });
  if (!response.ok) { let data={}; try { data=await response.json(); } catch {} throw new Error(data.error || `Request failed (${response.status})`); }
  const type=response.headers.get('Content-Type')||'';
  return type.includes('application/json') ? response.json() : response;
}
const post=(url,data)=>api(url,{method:'POST',body:JSON.stringify(data)});
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),3000);}
function visibleMapOptions(){return mapOptions;}
async function openOrganizationSignIn(){
  if(state.user){try{await post('/api/auth/logout',{});}catch(error){console.warn('Could not clear the previous session',error);}state.user=null;}
  state.authType='organization';state.authMode='login';state.nextScreen='upload';state.screen='login';render();
}
function logo(){return `<a class="logo" href="#" data-action="landing" aria-label="VASUDHA home"><img src="/assets/vasudha-logo.svg" alt="VASUDHA"></a>`;}
function header(active='Home', isLanding=false){
  const links=isLanding?['Home','Features','About','Contact']:['Home',...(state.user?.accountType==='organization'?['Upload Geotag Photos']:[]),'Analytics','About','Contact'];
  return `<header class="${isLanding?'landing-top':'topbar'}">${logo()}<nav class="nav">${links.map(label=>`<button class="${active===label?'active':''}" data-action="${label==='Home'?(isLanding?'landing':'explorer'):label==='Features'?'features':label==='About'?'about':label==='Contact'?'contact':label==='Upload Geotag Photos'?'upload':label.toLowerCase()}">${label}</button>`).join('')}</nav><div class="top-actions">${isLanding?'<button class="profile-btn" data-action="login">♙ &nbsp;Login</button>':`<button class="profile-btn" data-action="profile">♙ &nbsp;${esc(state.user?.name?.split(' ')[0]||'Profile')} ⌄</button>`}</div></header>`;
}
function landingArt(){return `<div class="hero-art" role="img" aria-label="Satellite view of a watershed with mapped land use, vegetation, water bodies, drainage and intervention locations"></div>`;}
function landing(){return `<div class="landing pdf-landing">${header('Home',true)}<section class="hero"><div class="hero-copy"><div class="eyebrow">GEOSPATIAL INTELLIGENCE FOR</div><h1>Smarter <em>Watershed</em><br>Development</h1><p>Visualize, analyze and interpret geo-coded images and satellite data to understand watershed conditions and monitor development outcomes.</p><div class="hero-rule"></div><button class="btn btn-primary hero-cta" data-action="login">Get Started <span>➜</span></button><div class="trust"><span>Trusted by</span><b><i>⌖</i>Satellite<br>Data</b><b><i>♧</i>Geo-coded<br>Images</b><b><i>▱</i>GIS<br>Analysis</b><b><i>♧</i>Sustainable<br>Future</b></div></div>${landingArt()}</section><div class="landing-wave"></div><div class="site-footer">© VASUDHA · Map data © OpenStreetMap contributors</div></div>`;}
function login(){
  const org=state.authType==='organization', registering=state.authMode==='register';
  return `<div class="login-screen"><section class="login-visual"><a class="login-brand" href="#" data-action="landing">${logo()}</a><div class="login-visual-copy"><div class="eyebrow">GEOSPATIAL INTELLIGENCE FOR</div><h1>Smarter <em>Watershed</em><br>Development</h1><p>Explore geospatial data to visualize, analyze and monitor watershed conditions for smarter development.</p><div class="hero-rule"></div></div><div class="login-pdf-art" role="img" aria-label="Watershed satellite illustration from the reference design"></div></section><section class="login-panel-wrap"><div class="login-card"><div class="login-heading"><div class="login-card-brand">${logo()}</div><h2>${registering?'Create Account':'Welcome'} <span>${registering?'':'Back'}</span></h2><p>${registering?'Create an account to access watershed insights and geospatial tools':'Sign in to access watershed insights and geospatial tools'}</p></div><div class="auth-switch"><button class="${!org?'active':''}" data-auth-mode="user">♙ &nbsp;User</button><button class="${org?'active':''}" data-auth-mode="organization">▣ &nbsp;Organisation</button></div><form id="auth-form" class="form-stack" data-mode="${registering?'register':'login'}"><label class="label ${registering?'':'hidden'}" id="name-wrap">Full name<input class="field" name="name" placeholder="Your name" ${registering?'required':''}></label><label class="label ${org&&registering?'':'hidden'}" id="org-wrap">Organisation name<input class="field" name="organization" placeholder="Your organisation" ${org&&registering?'required':''}></label><label class="label"><span class="sr-only">Email or username</span><input class="field" name="email" type="email" placeholder="Email / username" required></label><label class="label"><span class="sr-only">Password</span><span class="password-wrap"><input class="field" id="password-input" name="password" type="password" placeholder="Password" minlength="8" required><button class="password-toggle" type="button" data-action="toggle-password" aria-label="Show password">◉</button></span></label><button class="btn btn-primary" id="auth-submit">${registering?'Create account':'Login'} <span>→</span></button></form><p class="login-register">${registering?'Already have an account?':'New to VASUDHA?'} <button class="btn btn-soft btn-small" data-action="toggle-signup">${registering?'Login':'Create an account'}</button></p><p class="login-account-note">${org?'Organisation account includes geotagged photo uploads.':'User accounts can view watershed maps, analysis and reports.'}</p></div></section></div>`;
}
function sideLink(label, active, action, data=''){return `<button class="side-link ${active===label?'active':''}" data-action="${action}" ${data}> <span class="ico">${icon[label]||'◦'}</span>${label}</button>`;}
function sidebar(active='Land Use Map'){
  const analyticsSection=['analysis','analysis-home','reports','upload','intervention-detail'].includes(state.screen)||['Analytics','Reports','Upload Geotag Photos'].includes(active);
  const items=analyticsSection?analysisItems.map(label=>sideLink(label,state.analysis,'analysis',`data-analysis="${esc(label)}"`)).join(''):visibleMapOptions().map(x=>sideLink(x,active,'map',`data-map="${esc(x)}"`)).join('');
  return `<aside class="sidebar"><div class="side-label">${analyticsSection?'Analysis Tools':'Maps'}</div>${items}${analyticsSection?'':`<div class="side-label">Workspace</div>${sideLink('Analytics',active,'analytics')}${sideLink('Reports',active,'reports')}${state.user?.accountType==='organization'?sideLink('Upload Geotag Photos',active,'upload'):''}`}<div class="side-foot"><strong>Open data.<br>Ground observations.</strong><div class="leaf-wave"></div><small>Satellite imagery and mapped features, with field records entered by your team.</small></div></aside>`;
}
function shell(active,content){return `${header(active)}<main class="main">${content}<div class="leaf-wave"></div></main>`;}
function heading(title,desc,tools=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="head-tools">${tools}</div></div>`;}
function mapKind(label){if(/Drainage/.test(label))return 'drainage';if(/Vegetation/.test(label))return 'vegetation';if(/Water Bodies/.test(label))return 'water';if(/Intervention/.test(label))return 'interventions';if(/Geo-tagged Photos/.test(label))return 'photos';if(/Soil Moisture|Land Degradation/.test(label))return 'unavailable';return 'landuse';}
function interventionGlyph(type){
  const paths={
    'Afforestation':'<path d="M12 2 5 11h4l-5 7h6v4h4v-4h6l-5-7h4z" fill="currentColor"/>',
    'Check Dam':'<path d="M4 21h16M6 19V9l6-5 6 5v10M6 14h12M6 10h12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>',
    'Contour Trenching':'<path d="M3 6c3 0 3-3 6-3s3 3 6 3 3-3 6-3M3 12c3 0 3-3 6-3s3 3 6 3 3-3 6-3M3 18c3 0 3-3 6-3s3 3 6 3 3-3 6-3" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>',
    'Water Harvesting Structure':'<path d="M4 20h16M6 18V9l6-5 6 5v9M9 14h6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M12 9c-1 1.4-2 2.4-2 3.5a2 2 0 0 0 4 0c0-1.1-1-2.1-2-3.5" fill="currentColor"/>'
  };
  return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[type]||'<circle cx="12" cy="12" r="4" fill="currentColor"/>'}</svg>`;
}
function interventionTypeColor(type){return ({'Afforestation':'#19a96f','Check Dam':'#168fe0','Contour Trenching':'#f0ad20','Water Harvesting Structure':'#b329b8'})[type]||'#1684ad';}
function interventionStatusColor(status){return ({'Completed':'#0baf51','Ongoing':'#f5b013','Planned':'#f43438'})[status]||'#71899a';}
function interventionIcon(record){const typeColor=interventionTypeColor(record.type),statusColor=interventionStatusColor(record.status);return L.divIcon({className:'intervention-div-icon',html:`<span class="intervention-pin" style="--type-color:${typeColor};--status-color:${statusColor}" title="${esc(record.type)} · ${esc(record.status)}"><b>${interventionGlyph(record.type)}</b><i></i></span>`,iconSize:[38,42],iconAnchor:[19,21],popupAnchor:[0,-18]});}
function photosAtIntervention(record){
  if(state.user?.accountType!=='organization')return [];
  const maxDistance=0.12,rad=Math.PI/180;
  return state.uploaded.filter(photo=>{
    if(String(photo.intervention_id||'')===String(record.id))return true;
    if(photo.latitude==null||photo.longitude==null)return false;
    if(!Number.isFinite(Number(photo.latitude))||!Number.isFinite(Number(photo.longitude)))return false;
    const dLat=(Number(photo.latitude)-Number(record.latitude))*rad,dLon=(Number(photo.longitude)-Number(record.longitude))*rad;
    const a=Math.sin(dLat/2)**2+Math.cos(Number(record.latitude)*rad)*Math.cos(Number(photo.latitude)*rad)*Math.sin(dLon/2)**2;
    return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))<=maxDistance;
  });
}
function interventionPreview(record){
  const photos=photosAtIntervention(record),statusColor=interventionStatusColor(record.status),types=['Before','After'];
  const panels=types.map(stage=>{const items=photos.filter(photo=>photo.stage===stage);return `<section class="intervention-photo-panel"><strong>${stage}</strong>${items.length?`<div class="intervention-preview-photos">${items.map(photo=>`<img src="/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(stage)}: ${esc(photo.original_name)}" title="${esc(photo.original_name)}">`).join('')}</div>`:`<div class="intervention-photo-empty">${state.user?.accountType==='organization'?'No '+stage.toLowerCase()+' photos recorded at this site.':'Sign in with the organization account to view field photos.'}</div>`}</section>`;}).join('');
  const observations=photos.filter(photo=>!types.includes(photo.stage));
  return `<div class="intervention-preview-head"><span class="intervention-type-icon" style="--type-color:${interventionTypeColor(record.type)}">${interventionGlyph(record.type)}</span><div><span class="status-label" style="--status-color:${statusColor}">${esc(record.status)}</span><h2>${esc(record.type)}</h2><p>⌖ ${esc(record.area)}</p></div></div><div class="intervention-preview-gallery">${panels}</div>${observations.length?`<div class="intervention-observations"><strong>Other photos at this location · ${observations.length}</strong><div class="intervention-preview-photos">${observations.map(photo=>`<img src="/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.original_name)}" title="${esc(photo.original_name)}" loading="lazy">`).join('')}</div></div>`:''}<section class="intervention-analysis"><h3>Analysis &amp; Intervention Details</h3><div class="info-row"><span>Intervention type</span><strong>${esc(record.type)}</strong></div><div class="info-row"><span>Area / site</span><strong>${esc(record.area)}</strong></div><div class="info-row"><span>Status</span><strong>${esc(record.status)}</strong></div><div class="info-row"><span>Recorded date</span><strong>${esc(record.date)}</strong></div><div class="info-row"><span>Site photos</span><strong>${photos.length} recorded</strong></div>${record.details?`<p class="intervention-detail-notes">${esc(record.details)}</p>`:'<div class="blank-note">No analysis notes have been recorded for this intervention.</div>'}<div class="blank-note">Impact measurements are shown only when entered from verified field data.</div></section><button class="btn btn-primary intervention-full-detail" data-action="intervention-detail" data-id="${esc(record.id)}">Open full intervention details</button>`;
}
function thematicStyle(feature,kind){
  const p=feature.properties||{},g=feature.geometry||{},line=g.type==='LineString'||g.type==='MultiLineString';
  if(kind==='drainage'){
    const waterway=String(p.waterway||'');
    if(waterway==='river')return {color:'#00259a',weight:4.5,opacity:.98};
    if(['drain','ditch','canal'].includes(waterway))return {color:'#a3e7fe',weight:waterway==='canal'?2.8:1.8,opacity:.96};
    return {color:'#038cfa',weight:2.6,opacity:.96};
  }
  let fill='#20ae5c';
  if(kind==='vegetation'){
    const cover=p.natural||p.landuse||'';
    fill=['wood','forest','tree_row'].includes(cover)||p.landuse==='forest'?'#047138':['scrub','orchard','vineyard'].includes(cover)?'#75c878':'#d8fcb2';
    return {color:fill,weight:line?1.2:.65,opacity:.9,fillColor:fill,fillOpacity:line?0:.86};
  }
  const water=p.natural==='water'||p.waterway||p.landuse==='reservoir';
  const built=Boolean(p.building)||['residential','commercial','retail','industrial','construction','allotments'].includes(p.landuse);
  const barren=['bare_rock','sand','scree','quarry','brownfield'].includes(p.natural)||['quarry','landfill','brownfield'].includes(p.landuse);
  const agriculture=['farmland','farmyard','orchard','vineyard','meadow','allotments'].includes(p.landuse)||p.crop;
  if(water)fill='#02a8fc';else if(built)fill='#f25e6b';else if(barren)fill='#b0976f';else if(agriculture)fill='#f7ea7a';
  return {color:fill,weight:line?2:.7,opacity:.92,fillColor:fill,fillOpacity:line?0:.78};
}
function legendContent(label){
  const kind=mapKind(label),swatch=(color,text,extra='')=>`<div class="legend-item"><i class="legend-swatch" style="--swatch:${color};${extra}"></i><span>${text}</span></div>`;
  if(kind==='interventions'){
    const features=state.geo?.features||[],typeCount=type=>features.filter(feature=>feature.properties?.type===type).length,statusCount=status=>features.filter(feature=>feature.properties?.status===status).length;
    const typeRow=type=>`<div class="intervention-legend-row"><span class="intervention-type-icon small" style="--type-color:${interventionTypeColor(type)}">${interventionGlyph(type)}</span><span>${type}</span><b>${typeCount(type)}</b></div>`;
    const statusRow=status=>`<div class="intervention-legend-row"><i class="status-dot" style="--status-color:${interventionStatusColor(status)}"></i><span>${status}</span><b>${String(statusCount(status)).padStart(2,'0')}</b></div>`;
    return `<div class="card intervention-legend" id="intervention-legend"><div class="card-title">Watershed Interventions</div>${['Afforestation','Check Dam','Contour Trenching','Water Harvesting Structure'].map(typeRow).join('')}<hr class="divider"><div class="card-title">Map Status</div>${['Completed','Ongoing','Planned'].map(statusRow).join('')}</div>`;
  }
  if(kind==='drainage')return `<div class="card"><div class="card-title">Drainage Layers</div>${swatch('#00259a','Mainstream','height:6px;border-radius:6px')}${swatch('#038cfa','Tributaries','height:4px;border-radius:6px')}${swatch('#a3e7fe','Drainage Channels','height:3px;border-radius:6px')}</div>`;
  if(kind==='vegetation')return `<div class="card"><div class="card-title">Vegetation Layers</div>${swatch('#047138','Dense Vegetation')}${swatch('#75c878','Moderate Vegetation')}${swatch('#d8fcb2','Sparse Vegetation')}<p class="subtle">Classes follow mapped OSM land-cover types, not satellite-derived density.</p></div>`;
  return `<div class="card"><div class="card-title">Land Use Map</div>${swatch('#20ae5c','Forest / Vegetation')}${swatch('#f7ea7a','Agriculture')}${swatch('#02a8fc','Water Body')}${swatch('#f25e6b','Built-up Area')}${swatch('#b0976f','Barren / Land Degradation')}${swatch('#4bdde0','Selected Area','background:transparent;border:2px dashed #4bdde0')}<p class="subtle">Barren areas use mapped bare-land features; degradation is not measured.</p></div>`;
}
function mapCanvas(label='Land Use Map'){
  const kind=mapKind(label);
  return `<div class="map-canvas" id="map-canvas"><div class="leaflet-map" id="leaflet-map" data-kind="${kind}"></div><div class="map-caption">${icon[label]||'▤'} &nbsp;${esc(label)} <span class="subtle"> · Satellite imagery with live feature overlays</span></div><div class="live-map-note"><span id="live-map-note-text">Loading India map data…</span><button id="live-map-retry" class="btn btn-soft btn-small" data-action="reload-map-data" hidden>Retry</button></div></div>`;
}
function mapInfo(){const isIntervention=state.map==='Watershed Intervention';return `<div class="card" id="map-info"><div class="card-title">Map information</div><div class="info-row"><span>Selected area</span><strong>${esc(state.locationLabel)}</strong></div><div class="info-row"><span>Basemap</span><strong>Esri World Imagery</strong></div><div class="info-row"><span>Data source</span><strong>${isIntervention?'VASUDHA team records':'OpenStreetMap / Overpass'}</strong></div><div class="info-row"><span>Records in view</span><strong>${isIntervention?(state.geo?.features?.length??'Loading…'):(state.geo?.updated||'Waiting for live data')}</strong></div></div>`;}
function liveSummary(){const features=state.geo?.features||[];const tags={};for(const f of features){const p=f.properties||{};const category=p.landuse||p.natural||p.waterway||p.leisure||p.type||'Other mapped feature';tags[category]=(tags[category]||0)+1;}const rows=Object.entries(tags).sort((a,b)=>b[1]-a[1]).slice(0,7);return `<div class="card" id="live-summary"><div class="card-title">Live mapped features <span class="pill blue">${features.length} in map view</span></div>${state.geoError?`<div class="blank-note">${esc(state.geoError)}</div>`:rows.length?rows.map(([k,v])=>`<div class="info-row"><span>${esc(k)}</span><strong>${v}</strong></div>`).join(''):'<div class="blank-note">No mapped features returned for this view. Zoom or pan to another area.</div>'}<p class="subtle">Counts reflect mapped objects in the current view, not environmental measurements.</p></div>`;}
function explorer(){
  const current=state.map;
  const tools=`<input class="field search" id="map-search" placeholder="Search an area in India or enter lat, lon"><button class="btn btn-soft" data-action="search-map">⌕ Search area</button>`;
  return shell('Home',`${heading('Watershed Explorer','Search an Indian place or move the map; live OpenStreetMap features update for the visible area.',tools)}<div class="map-layout"><div class="card map-menu"><div class="card-title">Maps</div>${visibleMapOptions().map(x=>`<button class="map-tab ${current===x?'active':''}" data-action="map" data-map="${esc(x)}">${icon[x]} &nbsp;${x}</button>`).join('')}</div><div class="card map-frame"><div class="card-title">${esc(current)} <span class="subtle" id="area-label">${esc(state.locationLabel)}</span></div>${mapCanvas(current)}</div><div class="map-side grid">${legendContent(current)}${liveSummary()}${mapInfo()}</div></div><div class="grid two-col" style="margin-top:11px"><div class="card"><div class="card-title">Map controls</div><p class="subtle">Search an Indian place to highlight its mapped boundary when available. Pan or zoom to load real mapped features for any visible Indian area.</p><a class="btn btn-soft btn-small" href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noreferrer">Report a map issue ↗</a></div><div class="card"><div class="card-title">Live data sources</div><div class="info-row"><span>Satellite imagery</span><strong>Esri World Imagery</strong></div><div class="info-row"><span>Land cover / drainage</span><strong>OpenStreetMap · Overpass</strong></div><div class="info-row"><span>Selected boundary</span><strong>OpenStreetMap · Nominatim</strong></div></div></div>`,current);
}
function interventionTable(rows){if(!rows?.length)return '<div class="blank-note">No interventions yet. Add a record with coordinates to show it on the satellite map.</div>';return `<div style="overflow:auto"><table class="table"><thead><tr><th>Intervention</th><th>Location</th><th>Status</th><th>Date</th><th>Coordinates</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.type)}</strong><div class="subtle">${esc(r.id)}</div></td><td>${esc(r.area)}</td><td><span class="pill ${r.status==='Planned'?'orange':''}">${esc(r.status)}</span></td><td>${esc(r.date)}</td><td>${r.latitude}, ${r.longitude}</td><td><button class="btn btn-soft btn-small" data-action="intervention-detail" data-id="${esc(r.id)}">View details</button></td></tr>`).join('')}</tbody></table></div>`;}
function beforeAfterSection(record, photos, canUpload){
  return `<div class="before-after-grid">${['Before','After'].map(stage=>{const items=photos.filter(p=>p.stage===stage&&String(p.intervention_id)===String(record.id));return `<section class="ba-panel"><div class="ba-heading"><strong>${stage}</strong>${canUpload?`<button class="btn btn-soft btn-small" data-action="upload-evidence" data-id="${esc(record.id)}" data-stage="${stage}">＋ Add ${stage.toLowerCase()} image</button>`:''}</div>${items.length?`<div class="ba-photos">${items.map(p=>`<figure class="photo-card"><img src="/uploads/${encodeURIComponent(p.filename)}" alt="${esc(stage)} photo: ${esc(p.original_name)}"><figcaption>${esc(p.original_name)}<small>${esc(p.uploaded_at||'')}</small></figcaption></figure>`).join('')}</div>`:`<div class="ba-empty">${canUpload?`No ${stage.toLowerCase()} image yet. Upload a real site photo and label it “${stage}” to show it here.`:'No organization comparison photos are available for this record.'}</div>`}</section>`;}).join('')}</div>`;
}
function analyticsBarCard(title, rows, empty){
  const present=rows.filter(([,count])=>count>0),max=Math.max(1,...present.map(([,count])=>count));
  return `<section class="card analytics-chart"><div class="card-title">${esc(title)}<span class="pill blue">${present.reduce((n,[,v])=>n+v,0)} total</span></div>${present.length?`<div class="analytics-bars">${present.map(([label,count])=>`<div class="analytics-bar-row"><span title="${esc(label)}">${esc(label)}</span><div class="analytics-bar-track"><i style="width:${Math.max(3,count/max*100)}%"></i></div><strong>${count}</strong></div>`).join('')}</div>`:`<div class="blank-note">${esc(empty)}</div>`}</section>`;
}
function analyticsCharts(){
  const categories={};for(const f of state.geo?.features||[]){const p=f.properties||{},key=p.landuse||p.natural||p.waterway||p.leisure||p.type||'Other mapped feature';categories[key]=(categories[key]||0)+1;}
  const statuses={};for(const r of state.interventions)statuses[r.status||'Unspecified']=(statuses[r.status||'Unspecified']||0)+1;
  const stages={Before:0,After:0,Observation:0};for(const p of state.uploaded){const key=stages[p.stage]===undefined?'Observation':p.stage;stages[key]++;}
  const photoMonths={},interventionMonths={};for(const p of state.uploaded){const month=String(p.uploaded_at||'').slice(0,7);if(month)photoMonths[month]=(photoMonths[month]||0)+1;}for(const r of state.interventions){const month=String(r.date||'').slice(0,7);if(month)interventionMonths[month]=(interventionMonths[month]||0)+1;}
  const featureRows=Object.entries(categories).sort((a,b)=>b[1]-a[1]).slice(0,8);
  return `${analyticsBarCard('Mapped features by OSM tag',featureRows,'No OpenStreetMap features in the current map view.')}${analyticsBarCard('Intervention records by status',Object.entries(statuses),'No intervention records have been entered.')}${state.user?.accountType==='organization'?analyticsBarCard('Organization photos by stage',Object.entries(stages),'No organization field photos have been uploaded.'):`<section class="card analytics-chart"><div class="card-title">Organization photo evidence</div><div class="blank-note">Sign in with an organization account to view its private field photos and before/after evidence.</div></section>`}${state.user?.accountType==='organization'?analyticsBarCard('Photo uploads by month',Object.entries(photoMonths).sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),'No dated photo uploads are available.'):''}${analyticsBarCard('Intervention records by month',Object.entries(interventionMonths).sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),'No dated intervention records are available.')}`;
}
function organizationPhotoGallery(){
  if(state.user?.accountType!=='organization')return `<div class="card full"><div class="card-title">Organization field images</div><div class="blank-note">Organization photo evidence is visible only to organization accounts.</div></div>`;
  const photos=state.uploaded.slice(0,8);
  return `<div class="card full"><div class="card-title">Organization field images <span class="pill blue">${state.uploaded.length} real uploads</span><button class="btn btn-soft btn-small" data-action="upload">＋ Upload images</button></div>${photos.length?`<div class="analytics-photo-grid">${photos.map(p=>`<article class="analytics-photo"><img src="/uploads/${encodeURIComponent(p.filename)}" alt="Field photo: ${esc(p.original_name)}"><div><strong>${esc(p.original_name)}</strong><small>${esc(p.stage||'Observation')} · ${esc(p.category||'Field photo')}</small><small>${p.latitude}, ${p.longitude}</small><button class="btn btn-soft btn-small" data-action="classify-photo" data-id="${p.id}">Classify / link</button></div></article>`).join('')}</div>`:'<div class="blank-note">No real field images uploaded yet. Use Upload images to add organization photos with GPS coordinates.</div>'}</div>`;
}
function analyticsHome(){
  const controls=`<input id="analytics-search" class="field search" placeholder="Search place or lat, lon"><button class="btn btn-soft btn-small" data-action="search-analytics-map">⌕ Find</button><button class="btn btn-primary btn-small" data-action="reports">Reports</button>`;
  return shell('Analytics',`${heading('Watershed Analysis','Explore real map features, field images and intervention records.',controls)}<div class="grid four-col">${metricCard('OSM features in view',state.geo?.features?.length??'Loading','Current map extent','🗺')}${metricCard('Intervention records',state.interventions.length,'Stored team records','♧')}${state.user.accountType==='organization'?metricCard('GPS field photos',state.uploaded.length,'Organization uploads','▧'):metricCard('Map imagery','Satellite','Esri World Imagery','🌍')}${metricCard('Before / after photos',state.uploaded.filter(p=>p.stage==='Before'||p.stage==='After').length,'Linked intervention evidence','◉')}</div><div class="dashboard-grid" style="margin-top:11px"><div class="card"><div class="card-title">Analysis Tools</div>${analysisItems.filter(x=>x!=='Select Area'&&x!=='Reports').map(x=>`<button class="side-link" data-action="analysis" data-analysis="${esc(x)}">${icon[x]||'◦'} &nbsp;${x}</button>`).join('')}</div><div class="card"><div class="card-title">Watershed satellite map <span class="pill blue">Live map features</span></div>${mapCanvas('Land Use Map')}<div class="chart-legend"><span><i class="dot" style="background:#0eaf82"></i>OSM features</span><span><i class="dot" style="background:#087dbb"></i>Satellite imagery</span></div></div><div class="grid">${liveSummary()}<div class="card"><div class="card-title">Data source status</div><div class="info-row"><span>Imagery</span><strong>Esri World Imagery</strong></div><div class="info-row"><span>Mapped features</span><strong>OpenStreetMap / Overpass</strong></div><div class="info-row"><span>Field photos</span><strong>${state.user.accountType==='organization'?'Private organization records':'Organization only'}</strong></div><p class="subtle">Remote sensing indices require an analysis-ready satellite or sensor dataset; basemap tiles are not used to invent values.</p></div></div><div class="card full"><div class="card-title">Analytics from real records <button class="btn btn-soft btn-small" data-action="reload-map-data">↻ Refresh map data</button></div><div id="analytics-chart-grid" class="analytics-chart-grid">${analyticsCharts()}</div></div>${organizationPhotoGallery()}<div class="card full"><div class="card-title">Interventions entered by your team <button class="btn btn-soft btn-small" data-action="new-intervention">＋ Add intervention</button></div>${interventionTable(state.interventions)}</div></div>`,'Select Area');
}
function analysis(){
  const selected=state.analysis==='Select Area'?'Land Use':state.analysis,kind=mapKind(selected);
  const tools=`<span class="pill blue">${kind==='unavailable'?'No verified data feed':'Live mapped features'}</span><button class="btn btn-primary btn-small" data-action="reload-map-data">↻ Refresh</button>`;
  const photoCount=state.user.accountType==='organization'?`<div class="info-row"><span>GPS field photos</span><strong>${state.uploaded.length}</strong></div>`:'';
  const typeNotes={
    'Land Use':'Shows land-use polygons and natural features mapped in OpenStreetMap. Counts are not a remote-sensing classification.',
    'Drainage':'Shows mapped rivers, streams, canals and drains from OpenStreetMap.',
    'Vegetation':'Shows mapped forest, orchard, meadow and natural-vegetation features from OpenStreetMap.',
    'Water Bodies':'Shows mapped water polygons and reservoirs from OpenStreetMap.',
    'Interventions':'Shows georeferenced intervention records entered by signed-in teams.',
    'Soil Moisture':'No verified soil-moisture raster or sensor feed is connected.',
    'Land Degradation':'No verified degradation dataset is connected. No risk score is estimated.'
  };
  return shell('Analytics',`${heading(`${esc(selected)} Analysis`,esc(typeNotes[selected]||'Real mapped features from OpenStreetMap.'),tools)}<div class="map-layout"><div class="card"><div class="card-title">Selected analysis</div><div class="pill blue">${esc(selected)}</div><hr class="divider"><div class="info-row"><span>Area</span><strong>PDF reference point</strong></div><div class="info-row"><span>Source</span><strong>${kind==='interventions'?'VASUDHA team records':kind==='unavailable'?'Not connected':'OpenStreetMap'}</strong></div><div class="info-row"><span>Features in view</span><strong>${state.geo?.features?.length??'—'}</strong></div>${photoCount}<button class="btn btn-soft btn-small" style="margin-top:9px" data-action="reports">View report</button></div><div class="card"><div class="card-title">${esc(selected)} map · satellite view</div>${mapCanvas(selected)}<div class="tool-row" style="margin-top:8px"><span class="pill blue">${state.geo?.features?.length??0} mapped features in view</span><span class="pill">Satellite imagery · Esri</span></div></div><div class="grid">${liveSummary()}<div class="card"><div class="card-title">Data layers</div><div class="info-row"><span>World Imagery</span><strong>Satellite base layer</strong></div><div class="info-row"><span>Feature overlay</span><strong>${kind==='unavailable'?'None':kind==='interventions'?'Team records':'OSM query'}</strong></div><div class="info-row"><span>Capture date</span><strong>See imagery source metadata</strong></div><p class="subtle">Satellite imagery is a visual basemap, not analysis-ready imagery.</p></div></div><div class="card full"><div class="card-title">Team field records <button class="btn btn-soft btn-small" data-action="new-intervention">＋ Add record</button></div>${interventionTable(state.interventions)}</div></div>`,selected==='Reports'?'Reports':selected);
}
function reports(){
  const comparisons=state.interventions.length?state.interventions.map(r=>`<div class="report-comparison"><div class="card-title">${esc(r.type)} · ${esc(r.area)} <button class="btn btn-soft btn-small" data-action="intervention-detail" data-id="${esc(r.id)}">View record</button></div>${beforeAfterSection(r,state.uploaded,state.user?.accountType==='organization')}</div>`).join(''):'<div class="blank-note">Add an intervention record first, then link organization photos to compare its before and after condition.</div>';
  return shell('Reports',`${heading('District Watershed Report','Satellite map, live mapped features and field records entered by your organization.','<button class="btn btn-primary" data-action="export-pdf">↓ Download PDF</button><button class="btn btn-soft" data-action="share">↗ Share Report</button>')}<div class="grid four-col">${metricCard('Mapped features',state.geo?.features?.length??'—','Current satellite map view','🗺')}${metricCard('Interventions',state.interventions.length,'Team records with coordinates','♧')}${state.user?.accountType==='organization'?metricCard('Geotagged photos',state.uploaded.length,'Organization field records','▧'):metricCard('Feature source','OpenStreetMap','© contributors','〰')}${metricCard('Remote sensing values','Not connected','No sensor dataset supplied','◉')}</div><div class="dashboard-grid" style="margin-top:11px"><div class="card"><div class="card-title">District satellite map <span class="pill">PDF reference point</span></div>${mapCanvas('Land Use Map')}</div><div class="card"><div class="card-title">Live mapped features</div>${liveSummary()}<div class="info-row"><span>Imagery</span><strong>Esri World Imagery</strong></div><div class="info-row"><span>Feature source</span><strong>OpenStreetMap / Overpass</strong></div><div class="info-row"><span>Reference center</span><strong>23.64° N, 77.12° E</strong></div></div><div class="card"><div class="card-title">Data coverage</div><div class="blank-note">NDVI, soil moisture, land degradation, historical comparisons and watershed totals need an actual boundary and verified imagery or sensor data. None are inferred from the satellite basemap.</div><button class="btn btn-soft btn-small" style="margin-top:9px" data-action="export-json">Export source data (JSON)</button></div><div class="card full"><div class="card-title">Before and after site photos <span class="pill">${state.uploaded.filter(p=>p.stage==='Before'||p.stage==='After').length} tagged</span></div><p class="subtle">Only organization photos explicitly linked to an intervention and tagged Before or After appear in this comparison.</p>${comparisons}</div><div class="card full"><div class="card-title">Major interventions <span class="pill">${state.interventions.length} recorded</span></div>${interventionTable(state.interventions)}</div></div>`);
}
function interventionDetail(){
  const record=state.interventions.find(item=>item.id===state.activeIntervention);
  if(!record)return shell('Home',`${heading('Intervention details','This record is no longer available.','<button class="btn btn-soft" data-action="back-to-map">Back to Map</button>')}`);
  const photos=photosAtIntervention(record),statusColor=interventionStatusColor(record.status),stagePanel=stage=>{const items=photos.filter(photo=>photo.stage===stage);return `<section class="ba-panel"><div class="ba-heading"><strong>${stage}</strong><span class="pill">${items.length} photos</span></div>${items.length?`<div class="intervention-detail-photos">${items.map(photo=>`<figure class="photo-card"><img src="/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(stage)} photo: ${esc(photo.original_name)}"><figcaption>${esc(photo.original_name)}<small>${esc(photo.uploaded_at||'')}</small></figcaption></figure>`).join('')}</div>`:`<div class="ba-empty">No ${stage.toLowerCase()} photo is recorded for this site.</div>`}</section>`;};
  const otherPhotos=photos.filter(photo=>!['Before','After'].includes(photo.stage));
  return shell('Home',`<div class="intervention-detail-layout"><main class="intervention-detail-main"><div class="intervention-detail-actions"><button class="btn btn-soft btn-small" data-action="back-to-map">‹ Back to Map</button><span class="status-label" style="--status-color:${statusColor}">${esc(record.status)}</span><button class="btn btn-primary btn-small" data-action="upload-evidence" data-id="${esc(record.id)}" data-stage="Observation">Upload Geotag Photos</button></div><div class="intervention-detail-title"><span class="intervention-type-icon large" style="--type-color:${interventionTypeColor(record.type)}">${interventionGlyph(record.type)}</span><div><h1>${esc(record.type)}</h1><p>⌖ ${esc(record.area)} · ${record.latitude}, ${record.longitude}</p></div></div><div class="intervention-detail-gallery">${stagePanel('Before')}${stagePanel('After')}</div><div class="grid two-col intervention-facts"><section class="card"><div class="card-title">Analysis &amp; Intervention Details</div><div class="info-row"><span>Intervention Type</span><strong>${esc(record.type)}</strong></div><div class="info-row"><span>Status</span><strong>${esc(record.status)}</strong></div><div class="info-row"><span>Recorded Date</span><strong>${esc(record.date)}</strong></div><div class="info-row"><span>Field Photos</span><strong>${photos.length}</strong></div><div class="intervention-record-notes">${record.details?esc(record.details):'No analysis notes have been recorded for this intervention.'}</div></section><section class="card"><div class="card-title">Project Impact</div><div class="impact-stat"><strong>${otherPhotos.length+photos.filter(p=>p.stage==='Before'||p.stage==='After').length}</strong><span>Verified site photos</span></div><div class="blank-note">No measured project impact values are stored for this site. No estimates are shown.</div></section></div>${otherPhotos.length?`<section class="card"><div class="card-title">Other Photos at This Site</div><div class="intervention-detail-photos">${otherPhotos.map(photo=>`<figure class="photo-card"><img src="/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.original_name)}"><figcaption>${esc(photo.original_name)}<small>${esc(photo.stage||photo.category||'Field photo')} · ${esc(photo.uploaded_at||'')}</small></figcaption></figure>`).join('')}</div></section>`:''}<section class="card watershed-impact"><div class="card-title">Watershed Impact</div><p>${record.details?esc(record.details):'No verified impact assessment has been recorded for this intervention.'}</p></section></main><aside class="intervention-detail-side"><section class="card"><div class="card-title">Site Information</div>${mapCanvas('Watershed Intervention')}<div class="info-row"><span>Location</span><strong>${esc(record.area)}</strong></div><div class="info-row"><span>Latitude / Longitude</span><strong>${Number(record.latitude).toFixed(5)}, ${Number(record.longitude).toFixed(5)}</strong></div><div class="info-row"><span>Coordinate source</span><strong>Saved intervention record</strong></div></section><section class="card"><div class="card-title">Intervention Details</div><div class="info-row"><span>Intervention Type</span><strong>${esc(record.type)}</strong></div><div class="info-row"><span>Status</span><strong>${esc(record.status)}</strong></div><div class="info-row"><span>Recorded Date</span><strong>${esc(record.date)}</strong></div><div class="info-row"><span>Area Treated</span><strong>Not recorded</strong></div></section></aside></div>`);
}
async function openInterventionDetail(id){
  const record=state.interventions.find(item=>String(item.id)===String(id));if(!record){toast('Intervention record was not found');return;}
  state.activeIntervention=record.id;state.map='Watershed Intervention';state.screen='intervention-detail';await refresh();render();
  if(state.mapInstance&&record.latitude!=null&&record.longitude!=null)state.mapInstance.setView([Number(record.latitude),Number(record.longitude)],15);
}
function metricCard(label,value,note,emoji){return `<div class="card metric"><div class="metric-label">${emoji} &nbsp;${label}</div><div class="metric-value" style="font-size:18px" ${label==='OSM features in view'?'data-live-count="osm"':''}>${esc(value)}</div><div class="metric-note">${esc(note)}</div></div>`;}
function photoTile(p){return `<div class="photo-card"><img src="${p.dataURL}" alt="${esc(p.name)}"><p title="${esc(p.name)}">${esc(p.name)}</p><button data-remove-photo="${esc(p.key)}" style="position:absolute;right:5px;top:5px;border:0;border-radius:50%;background:#fff;color:#567;padding:3px 7px">×</button></div>`;}
function uploadPage(){
  return shell('Upload Geotag Photos',`${heading('Organization field photos','Upload a field image with a GPS position. Before and after images can be linked to an intervention.',`<button class="btn btn-soft" data-action="my-photos">▧ Uploaded photos</button>`)}<div class="grid two-col"><div class="grid"><div class="card"><div class="card-title">Upload geotagged photos <span class="pill blue">JPG / PNG · 10 MB max</span></div><label class="dropzone" for="photo-input"><span class="cloud">☁</span><strong>Drop photos here or browse</strong><small>Images are stored in this local VASUDHA workspace.</small></label><input id="photo-input" class="hidden" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="form-stack" style="grid-template-columns:1fr 1fr;margin-top:11px"><label class="label">Photo category<select id="photo-category" class="field"><option>Field observation</option><option>Vegetation</option><option>Water body</option><option>Soil condition</option><option>Intervention progress</option></select></label><label class="label">Image stage<select id="photo-stage" class="field"><option value="Observation" ${state.uploadStage==='Observation'?'selected':''}>Observation</option><option value="Before" ${state.uploadStage==='Before'?'selected':''}>Before intervention</option><option value="After" ${state.uploadStage==='After'?'selected':''}>After intervention</option></select></label><label class="label">Related intervention<select id="photo-intervention" class="field"><option value="">Not linked</option>${state.interventions.map(item=>`<option value="${esc(item.id)}" ${String(state.uploadForIntervention)===String(item.id)?'selected':''}>${esc(item.type)} · ${esc(item.area)}</option>`).join('')}</select></label><label class="label">Location name<input id="photo-location" class="field" placeholder="Village or field site"></label><label class="label">Latitude<input id="photo-lat" class="field" type="number" step="any" required placeholder="GPS latitude"></label><label class="label">Longitude<input id="photo-lon" class="field" type="number" step="any" required placeholder="GPS longitude"></label></div><button class="btn btn-soft btn-small" style="margin-top:9px" data-action="get-location">⌖ Use device location</button></div><div class="card"><div class="card-title">Selected photos <button class="btn btn-soft btn-small" data-action="clear-photos">Clear</button></div><div class="photo-grid">${state.photos.map(photoTile).join('')||'<div class="blank-note" style="grid-column:1/-1">Choose one or more images to preview them.</div>'}</div><div class="tool-row" style="justify-content:flex-end;margin-top:10px"><span class="subtle">${state.photos.length} selected</span><button class="btn btn-primary" data-action="upload-photos">Upload photos ↑</button></div></div></div><div class="grid"><div class="card"><div class="card-title">Photo metadata</div><p class="subtle">Each saved field photo includes the selected category, timestamp and coordinates. Select Before or After and link an intervention to display a real comparison.</p><div class="info-row"><span>Account</span><strong>${esc(state.user?.organization||'Organization')}</strong></div><div class="info-row"><span>Location permission</span><strong>Only requested when you click the location button</strong></div><div class="info-row"><span>Map source</span><strong>OpenStreetMap</strong></div></div><div class="card"><div class="card-title">Recent uploads</div><div>${state.uploaded.map(p=>`<div class="info-row"><span>${esc(p.original_name)}<br><small>${esc(p.stage||'Observation')} · ${p.latitude}, ${p.longitude}</small></span><strong>${esc(p.category)}</strong></div>`).join('')||'<div class="blank-note">No geotagged photos uploaded yet.</div>'}</div></div></div></div>`);
}
function render(){
  if(['explorer','analysis','analysis-home','reports','upload','intervention-detail'].includes(state.screen)&&!state.user)state.screen='login';
  if(state.screen==='upload'&&state.user?.accountType!=='organization')state.screen='explorer';
  const app=$('#app');
  if(state.screen==='landing')app.innerHTML=landing();else if(state.screen==='login')app.innerHTML=login();else if(state.screen==='reports')app.innerHTML=reports();else if(state.screen==='upload')app.innerHTML=uploadPage();else if(state.screen==='intervention-detail')app.innerHTML=interventionDetail();else if(state.screen==='analysis-home')app.innerHTML=analyticsHome();else if(state.screen==='analysis')app.innerHTML=analysis();else app.innerHTML=explorer();
  bind();
  if(['explorer','analysis','analysis-home','reports','intervention-detail'].includes(state.screen))initializeMap();
}
function setScreen(screen){if(['explorer','analysis','analysis-home','reports','upload','intervention-detail'].includes(screen)&&!state.user){state.screen='login';render();return;}state.screen=screen;render();window.scrollTo(0,0);}
function showModal(title,body){const node=document.createElement('div');node.className='modal-backdrop';node.innerHTML=`<section class="modal"><button class="modal-close" data-action="close-modal">×</button><h2>${title}</h2>${body}</section>`;document.body.append(node);node.addEventListener('click',async e=>{if(e.target===node||e.target.closest('[data-action="close-modal"]'))node.remove();const target=e.target.closest('[data-action]'),action=target?.dataset.action;if(action==='use-selected-coords'){const c=state.selectedCoords;if(c){$('#int-lat').value=c.lat;$('#int-lon').value=c.lon;toast('Coordinates added to the intervention form');}}if(action==='intervention-detail'){node.remove();await openInterventionDetail(target.dataset.id);}});const form=node.querySelector('#intervention-form');if(state.selectedCoords&&form){$('#int-lat',node).value=state.selectedCoords.lat;$('#int-lon',node).value=state.selectedCoords.lon;}form?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await post('/api/interventions',d);node.remove();await refresh();render();toast('Intervention saved with coordinates');}catch(err){toast(err.message);}});const photoForm=node.querySelector('#photo-classify-form');photoForm?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await post('/api/photos/update',{...d,id:Number(d.id)});node.remove();await refresh();render();toast('Photo classification saved');}catch(err){toast(err.message);}});}
function bind(){
  $$('[data-action]').forEach(button=>button.addEventListener('click',async()=>{
    const action=button.dataset.action;
    try{
      if(action==='landing')return setScreen('landing');
      if(action==='login')return setScreen('login');
      if(action==='toggle-signup'){state.authMode=state.authMode==='login'?'register':'login';return render();}
      if(action==='continue'){return setScreen('explorer');}
      if(action==='toggle-password'){const field=$('#password-input');if(field){field.type=field.type==='password'?'text':'password';button.setAttribute('aria-label',field.type==='password'?'Show password':'Hide password');}return;}
      if(action==='explorer'){return setScreen('explorer');}
      if(action==='analytics'){state.analysis='Select Area';state.screen='analysis-home';await refresh();render();return;}
      if(action==='analysis'){state.analysis=button.dataset.analysis;state.screen=state.analysis==='Reports'?'reports':state.analysis==='Select Area'?'analysis-home':'analysis';await refresh();render();return;}
      if(action==='intervention-detail'){state.activeIntervention=button.dataset.id;state.analysis='Interventions';state.screen='intervention-detail';await refresh();render();return;}
      if(action==='classify-photo'){const photo=state.uploaded.find(p=>String(p.id)===button.dataset.id);if(!photo)return;const interventionOptions=state.interventions.map(item=>`<option value="${esc(item.id)}" ${String(photo.intervention_id)===String(item.id)?'selected':''}>${esc(item.type)} · ${esc(item.area)}</option>`).join('');return showModal('Classify organization photo',`<div class="classify-photo-preview"><img src="/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.original_name)}"></div><p class="subtle">${esc(photo.original_name)} · GPS ${photo.latitude}, ${photo.longitude}</p><form id="photo-classify-form" class="form-stack"><input type="hidden" name="id" value="${photo.id}"><label class="label">Image stage<select class="field" name="stage"><option value="Observation" ${photo.stage==='Observation'?'selected':''}>Observation</option><option value="Before" ${photo.stage==='Before'?'selected':''}>Before intervention</option><option value="After" ${photo.stage==='After'?'selected':''}>After intervention</option></select></label><label class="label">Related intervention<select class="field" name="interventionId"><option value="">Not linked</option>${interventionOptions}</select></label><button class="btn btn-primary">Save photo classification</button></form>`);}
      if(action==='upload-evidence'){state.activeIntervention=button.dataset.id;state.uploadForIntervention=button.dataset.id;state.uploadStage=button.dataset.stage||'Before';if(state.user?.accountType!=='organization'){await openOrganizationSignIn();return;}state.screen='upload';await refresh();render();return;}
      if(action==='back-interventions'){state.analysis='Interventions';state.screen='analysis';await refresh();render();return;}
      if(action==='back-to-map'){state.map='Watershed Intervention';state.screen='explorer';render();return;}
      if(action==='reports'){state.analysis='Reports';state.screen='reports';await refresh();render();return;}
      if(action==='upload'){const session=await api('/api/me');state.user=session.user;if(!state.user||state.user.accountType!=='organization'){await openOrganizationSignIn();return;}state.uploadForIntervention=null;state.uploadStage='Observation';state.screen='upload';await refresh();render();return;}
      if(action==='map'){state.map=button.dataset.map||'Land Use Map';render();return;}
      if(action==='profile'){return showModal('VASUDHA account',`<p>Signed in as <strong>${esc(state.user?.name)}</strong><br>${esc(state.user?.email)}<br>${esc(state.user?.organization||'Personal workspace')} · ${state.user?.accountType==='organization'?'Organization':'User'} account</p><button class="btn btn-primary" data-action="logout">Sign out</button>`);}
      if(action==='logout'){await post('/api/auth/logout',{});state.user=null;state.geo=null;state.screen='login';toast('Signed out');render();return;}
      if(action==='theme'){document.body.classList.toggle('dark');return;}
      if(action==='features'){document.querySelector('.hero')?.scrollIntoView({behavior:'smooth'});return;}
      if(action==='about'||action==='contact'){return showModal(action==='about'?'About VASUDHA':'Contact',`<p>VASUDHA uses OpenStreetMap tiles and mapped features, plus geotagged field records your organization submits.</p><p>Map attribution: © OpenStreetMap contributors.</p><a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noreferrer">Report a map issue ↗</a>`);}
      if(action==='search-map'){const query=$('#map-search')?.value?.trim();if(!query){toast('Enter an Indian place or latitude, longitude');return;}const coordinates=/^\s*-?\d+(?:\.\d+)?\s*,\s*-?\d+(?:\.\d+)?\s*$/.test(query);const searchQuery=coordinates||/\bindia\b/i.test(query)?query:`${query}, India`;const result=await api('/api/search?q='+encodeURIComponent(searchQuery));state.locationLabel=result.label||searchQuery;state.selectedArea=result.boundary||null;state.selectedPoint=[result.lat,result.lon];const areaLabel=$('#area-label');if(areaLabel)areaLabel.textContent=state.locationLabel;if(state.mapInstance){if(result.bounds?.length===4){const [south,north,west,east]=result.bounds,span=Math.max(north-south,east-west);if(span>.35)state.mapInstance.setView([result.lat,result.lon],11);else state.mapInstance.fitBounds([[south,west],[north,east]],{maxZoom:13,padding:[18,18]});}else state.mapInstance.setView([result.lat,result.lon],13);drawSelectedArea();}toast('Selected area: '+(result.label||searchQuery));return;}
      if(action==='reload-map-data'){await loadGeoData();return;}
      if(action==='search-analytics-map'){const query=$('#analytics-search')?.value?.trim();if(!query){toast('Enter a place or latitude, longitude');return;}const result=await api('/api/search?q='+encodeURIComponent(query));state.mapInstance?.setView([result.lat,result.lon],13);toast('Map moved to '+result.label);return;}
      if(action==='locate'){state.mapInstance?.setView([23.64,77.12],12);return;}
      if(action==='get-location'){if(!navigator.geolocation){toast('This browser does not provide device location.');return;}navigator.geolocation.getCurrentPosition(pos=>{$('#photo-lat').value=pos.coords.latitude.toFixed(6);$('#photo-lon').value=pos.coords.longitude.toFixed(6);toast('Device coordinates added');},err=>toast(err.message||'Location permission was not granted.'),{enableHighAccuracy:true,timeout:12000});return;}
      if(action==='clear-photos'){state.photos=[];render();return;}
      if(action==='upload-photos'){await uploadSelected();return;}
      if(action==='my-photos'){await refresh();return showModal('Uploaded geotagged photos',state.uploaded.length?`<div class="photo-grid">${state.uploaded.map(p=>`<div class="photo-card"><img src="/uploads/${encodeURIComponent(p.filename)}" alt=""><p>${esc(p.original_name)}<br>${p.latitude}, ${p.longitude}</p></div>`).join('')}</div>`:'<div class="blank-note">No photos have been uploaded yet.</div>');}
      if(action==='new-intervention'){return showModal('Add intervention record',`<form id="intervention-form" class="form-stack"><label class="label">Type<select class="field" name="type"><option>Afforestation</option><option>Check Dam</option><option>Contour Trenching</option><option>Water Harvesting Structure</option><option>Other field intervention</option></select></label><label class="label">Location<input class="field" name="area" required placeholder="Village or site name"></label><label class="label">Status<select class="field" name="status"><option>Planned</option><option>Ongoing</option><option>Completed</option></select></label><label class="label">Date<input class="field" type="date" name="date"></label><label class="label">Analysis / field notes<textarea class="field" name="details" rows="3" maxlength="2000" placeholder="Enter observations or measured outcomes from the field"></textarea></label><div class="form-stack" style="grid-template-columns:1fr 1fr"><label class="label">Latitude<input class="field" id="int-lat" name="latitude" type="number" step="any" required></label><label class="label">Longitude<input class="field" id="int-lon" name="longitude" type="number" step="any" required></label></div><p class="subtle">Click the site on the intervention map to copy its coordinates, or enter a GPS position in India.</p><button class="btn btn-primary">Save record</button></form>`);}
      if(action==='use-selected-coords'){const c=state.selectedCoords;if(c){$('#int-lat').value=c.lat;$('#int-lon').value=c.lon;}return;}
      if(action==='export-csv'){downloadReport('csv');return;}
      if(action==='export-json'){downloadReport('json');return;}
      if(action==='export-pdf'){window.print();return;}
      if(action==='share'){if(navigator.share)await navigator.share({title:'VASUDHA watershed data',url:location.href});else{await navigator.clipboard.writeText(location.href);toast('Report link copied');}return;}
    }catch(error){toast(error.message||'Something went wrong');}
  }));
  $('#auth-form')?.addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget));try{const endpoint=state.authMode==='register'?'/api/auth/register':'/api/auth/login';await post(endpoint,{...values,accountType:state.authType});const session=await api('/api/me');if(!session.user)throw new Error('Sign-in did not create a session. Please try again.');state.user=session.user;state.authMode='login';await refresh();toast('Signed in successfully');const next=state.nextScreen==='upload'&&state.user.accountType==='organization'?'upload':'explorer';state.nextScreen=null;setScreen(next);}catch(error){toast(error.message);}});
  $$('[data-auth-mode]').forEach(button=>button.onclick=()=>{state.authType=button.dataset.authMode;render();});
  $('#photo-input')?.addEventListener('change',event=>addFiles(event.target.files));
  const drop=$('.dropzone');if(drop){drop.addEventListener('dragover',event=>{event.preventDefault();drop.style.background='#e2f7ed';});drop.addEventListener('dragleave',()=>drop.style.background='');drop.addEventListener('drop',event=>{event.preventDefault();addFiles(event.dataTransfer.files);});}
  $$('[data-remove-photo]').forEach(button=>button.onclick=()=>{state.photos=state.photos.filter(photo=>photo.key!==button.dataset.removePhoto);render();});
}
function addFiles(files){for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG or WebP image');continue;}if(file.size>10*1024*1024){toast(`${file.name} is larger than 10 MB`);continue;}if(state.photos.some(photo=>photo.name===file.name))continue;const reader=new FileReader();reader.onload=()=>{state.photos.push({key:crypto.randomUUID(),name:file.name,type:file.type,dataURL:reader.result});render();};reader.readAsDataURL(file);}}
async function uploadSelected(){
  if(!state.photos.length){toast('Choose photos to upload first');return;}
  const session=await api('/api/me');state.user=session.user;
  if(!state.user||state.user.accountType!=='organization'){await openOrganizationSignIn();return;}
  const latitude=$('#photo-lat')?.value,longitude=$('#photo-lon')?.value;
  if(!latitude||!longitude){toast('Add GPS coordinates or use device location before uploading');return;}
  const stage=$('#photo-stage')?.value||'Observation',interventionId=$('#photo-intervention')?.value||'';
  if((stage==='Before'||stage==='After')&&!interventionId){toast('Select the intervention to link this before/after photo');return;}
  for(const photo of state.photos){await post('/api/photos',{name:photo.name,mime:photo.type,data:photo.dataURL,category:$('#photo-category').value,stage,interventionId,location:$('#photo-location').value,latitude,longitude});}
  const target=interventionId||state.uploadForIntervention;state.photos=[];await refresh();if(target){state.activeIntervention=target;state.screen='intervention-detail';state.uploadForIntervention=null;}render();toast('Geotagged photos uploaded');
}
async function refresh(){
  if(!state.user)return;
  try{const [interventions,analytics]=await Promise.all([api('/api/interventions'),api('/api/analytics')]);state.interventions=interventions;state.analytics=analytics;if(state.user.accountType==='organization')state.uploaded=await api('/api/photos');}catch(error){console.warn(error);}
}
function drawSelectedArea(){
  if(!state.mapInstance)return;
  if(state.areaLayer){state.areaLayer.remove();state.areaLayer=null;}
  if(state.selectedArea||state.selectedPoint){state.areaLayer=L.featureGroup().addTo(state.mapInstance);if(state.selectedArea)L.geoJSON({type:'Feature',properties:{name:state.locationLabel},geometry:state.selectedArea},{pane:'selectedAreaPane',interactive:false,style:{color:'#4bdde0',weight:3,dashArray:'8 6',fill:false,opacity:.98}}).addTo(state.areaLayer);if(state.selectedPoint)L.circleMarker([state.selectedPoint[0],state.selectedPoint[1]],{pane:'selectedAreaPane',radius:6,color:'#fff',weight:2,fillColor:'#f1bf45',fillOpacity:1}).bindTooltip(esc(state.locationLabel)).addTo(state.areaLayer);}
}
async function loadGeoData(){
  const map=$('#leaflet-map');if(!map||!state.mapInstance)return;
  const requestId=++state.geoRequest;
  const kind=map.dataset.kind;state.geo=null;state.geoError='';const note=$('#live-map-note-text'),retry=$('#live-map-retry');if(note)note.textContent='Loading India map data…';if(retry)retry.hidden=true;
  if(kind==='unavailable'){state.geoError='No verified soil-moisture or land-degradation data source is connected. The real base map remains available.';if(note)note.textContent='No verified environmental dataset connected';updateLivePanels();return;}
  try{
    let result;
    if(kind==='interventions'){
      const b=state.mapInstance.getBounds(),bbox=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].join(',');
      result=await api('/api/geo?type=interventions&bbox='+encodeURIComponent(bbox));
    }else if(kind==='photos'){
      const b=state.mapInstance.getBounds(),bbox=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].join(',');
      result=await api('/api/geo?type=photos&bbox='+encodeURIComponent(bbox));
    }else{
      const b=state.mapInstance.getBounds(),bbox=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].join(',');
      result=await api('/api/geo?type='+kind+'&bbox='+encodeURIComponent(bbox));
    }
    if(requestId!==state.geoRequest)return;
    state.geo=result;
    if(state.geoLayer)state.geoLayer.remove();
    state.geoLayer=L.geoJSON(result,{style:f=>thematicStyle(f,kind),pointToLayer:(f,latlng)=>kind==='interventions'?L.marker(latlng,{icon:interventionIcon(f.properties||{})}):L.circleMarker(latlng,{radius:7,color:'#087dbb',fillColor:'#13b68a',fillOpacity:.85}),onEachFeature:(f,layer)=>{const p=f.properties||{},name=p.name||p.landuse||p.natural||p.waterway||p.type||'Mapped feature';if(kind==='interventions'){let clickTimer=null;layer.on('click',event=>{if(event.originalEvent)L.DomEvent.stop(event.originalEvent);clearTimeout(clickTimer);clickTimer=setTimeout(()=>{const record=state.interventions.find(item=>String(item.id)===String(p.id));if(record)showModal(`${record.type} · ${record.status}`,interventionPreview(record));},260);});layer.on('dblclick',event=>{if(event.originalEvent)L.DomEvent.stop(event.originalEvent);clearTimeout(clickTimer);openInterventionDetail(p.id);});return;}const osmLink=p.osm_id?`<br><a target="_blank" rel="noreferrer" href="https://www.openstreetmap.org/way/${esc(p.osm_id)}">View on OpenStreetMap ↗</a>`:'';const photoLink=p.filename?`<br><a target="_blank" rel="noreferrer" href="/uploads/${encodeURIComponent(p.filename)}">Open field photo ↗</a>`:'';layer.bindPopup(`<strong>${esc(name)}</strong><br><span>${esc(p.source||'OpenStreetMap feature')}</span>${osmLink}${photoLink}`);}}).addTo(state.mapInstance);
    if(note)note.textContent=`${result.features.length} live mapped features · © OpenStreetMap`;
  }catch(error){if(requestId!==state.geoRequest)return;state.geoError=error.message;if(note)note.textContent=error.message;if(retry)retry.hidden=false;}
  updateLivePanels();
}
function updateLivePanels(){const summary=$('#live-summary');if(summary)summary.outerHTML=liveSummary();const info=$('#map-info');if(info)info.outerHTML=mapInfo();const legend=$('#intervention-legend');if(legend)legend.outerHTML=legendContent('Watershed Intervention');const count=$('[data-live-count="osm"]');if(count)count.textContent=state.geo?.features?.length??'—';const charts=$('#analytics-chart-grid');if(charts)charts.innerHTML=analyticsCharts();const note=$('#live-map-note-text'),retry=$('#live-map-retry');if(note&&state.geoError)note.textContent=state.geoError;if(retry&&state.geoError)retry.hidden=false;}
function downloadReport(format){
  const features=state.geo?.features||[];
  if(!state.geo&&!state.geoError){toast('Wait for live map data to load before exporting.');return;}
  const report={generatedAt:new Date().toISOString(),source:state.geo?.source||'OpenStreetMap',mapUpdatedAt:state.geo?.updated||null,visibleFeatureCount:features.length,features,teamInterventions:state.interventions,organizationPhotos:state.user?.accountType==='organization'?state.uploaded.map(({id,original_name,category,location,latitude,longitude,uploaded_at,stage,intervention_id})=>({id,original_name,category,location,latitude,longitude,uploaded_at,stage,intervention_id})):undefined};
  let contents,type,name;
  if(format==='json'){contents=JSON.stringify(report,null,2);type='application/json';name='waterscope-live-data.json';}
  else{const rows=[['record_type','source_id','category','name','latitude','longitude','status']];for(const f of features){const p=f.properties||{},coordinates=f.geometry?.type==='Point'?f.geometry.coordinates:(f.geometry?.coordinates?.[0]||[]).reduce((a,c)=>[a[0]+c[0]/Math.max(1,f.geometry.coordinates[0].length),a[1]+c[1]/Math.max(1,f.geometry.coordinates[0].length)],[0,0]);rows.push(['OpenStreetMap',p.osm_id||'',p.landuse||p.natural||p.waterway||p.leisure||'',p.name||'',coordinates[1],coordinates[0],'']);}for(const r of state.interventions)rows.push(['Team intervention',r.id,r.type,r.area,r.latitude,r.longitude,r.status]);contents=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');type='text/csv;charset=utf-8';name='waterscope-live-data.csv';}
  const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);toast(`${format.toUpperCase()} data downloaded`);
}
function initializeMap(){
  const node=$('#leaflet-map');if(!node)return;if(!window.L){const note=$('#live-map-note-text');if(note)note.textContent='Map library unavailable. Check your internet connection.';return;}
  let center=[23.64,77.12],zoom=12;if(state.mapInstance){const oldCenter=state.mapInstance.getCenter();center=[oldCenter.lat,oldCenter.lng];zoom=state.mapInstance.getZoom();state.mapInstance.remove();state.mapInstance=null;state.geoLayer=null;state.areaLayer=null;}
  const map=L.map(node,{scrollWheelZoom:true,maxBounds:[[6.4,68],[37.2,97.5]],maxBoundsViscosity:.85}).setView(center,zoom);state.mapInstance=map;map.createPane('selectedAreaPane');map.getPane('selectedAreaPane').style.zIndex=450;drawSelectedArea();
  const satellite=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Sources: <a href="https://www.esri.com/">Esri</a>, DigitalGlobe, GeoEye, i-cubed, USDA FSA, USGS, AEX, Getmapping, Aerogrid, IGN, IGP, swisstopo, and the GIS User Community'}).addTo(map);
  const street=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'Map data &copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'});
  L.control.layers({'Satellite imagery':satellite,'Street map':street},null,{position:'topright',collapsed:true}).addTo(map);
  let moveTimer;map.on('moveend',()=>{clearTimeout(moveTimer);moveTimer=setTimeout(()=>loadGeoData(),500);});
  map.on('click',event=>{state.selectedCoords={lat:event.latlng.lat.toFixed(6),lon:event.latlng.lng.toFixed(6)};L.popup().setLatLng(event.latlng).setContent(`<strong>Selected map position</strong><br>${state.selectedCoords.lat}, ${state.selectedCoords.lon}<br><button type="button" id="copy-map-coords">Use these coordinates</button>`).openOn(map);setTimeout(()=>$('#copy-map-coords')?.addEventListener('click',()=>{const lat=$('#int-lat'),lon=$('#int-lon');if(lat&&lon){lat.value=state.selectedCoords.lat;lon.value=state.selectedCoords.lon;toast('Coordinates copied');}else toast(`${state.selectedCoords.lat}, ${state.selectedCoords.lon}`);}),0);});
  setTimeout(()=>map.invalidateSize(),20);loadGeoData();
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-map][data-action="map"]');if(button){state.map=button.dataset.map;}});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target?.id==='map-search'){event.preventDefault();$('[data-action="search-map"]')?.click();}});
render();
api('/api/me').then(async result=>{if(result.user){state.user=result.user;state.authType=result.user.accountType||'user';await refresh();if(state.screen==='login')render();}}).catch(()=>{});
